@OptIn(ExperimentalAnimationApi::class)
@Composable
fun DashboardContent(
    project: Context,
    onStatusUpdate: (String, String?) -> Unit,
    onToggleProjectManagement: (Boolean) -> Unit,
    onRecalculateTime: () -> Unit,
    contextTimeMetrics: ContextTimeMetrics?,
) {
    var showStatusDialog by remember { mutableStateOf(false) }

    Column(
        modifier =
            Modifier
                .fillMaxSize()
                .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        AnimatedContent(
            targetState = project.isContextManagementEnabled == true,
            label = "DashboardContentAnimation",
        ) { isManagementEnabled ->
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp),
            ) {
                if (!isManagementEnabled) {
                    EnableSupportCard(onEnable = { onToggleProjectManagement(true) })
                } else {
                    StatusDisplayCard(status = project.contextStatus ?: ContextStatusValues.NO_PLAN, statusText = project.contextStatusText, onClick = {
                        showStatusDialog = true
                    })

                    contextTimeMetrics?.let { metrics ->
                        Spacer(modifier = Modifier.height(8.dp))
                        MetricsDisplayCard(metrics = metrics)
                    }

                    OutlinedButton(onClick = onRecalculateTime) {
                        Text("Recalculate")
                    }
                    Text(
                        "Тут будуть метрики та рекомендовані дії",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
        }
    }

    if (showStatusDialog) {
        UpdateStatusDialog(
            currentStatus = project.contextStatus ?: ContextStatusValues.NO_PLAN,
            currentStatusText = project.contextStatusText ?: "",
            onDismissRequest = {
                showStatusDialog = false
            },
            onSave = { newStatus, newText ->
                onStatusUpdate(newStatus, newText)
                showStatusDialog = false
            },
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
