                Spacer(modifier = Modifier.height(4.dp))
                Text(ContextStatusValues.getDisplayName(status), style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                if (!statusText.isNullOrBlank()) {
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = statusText,
